import{_ as c,C as r,o as n,c as u,a5 as t,E as i,j as a,a as l,b as B,w as o,a6 as d}from"./chunks/framework.D_J2JZBr.js";const S=JSON.parse('{"title":"计算机体系结构与系统","description":"从 CS110、RISC-V 到开源 GPGPU，认识上科大的计算机架构与系统研究入口。","frontmatter":{"title":"计算机体系结构与系统","description":"从 CS110、RISC-V 到开源 GPGPU，认识上科大的计算机架构与系统研究入口。"},"headers":[],"relativePath":"explore-ic/research-directions/architecture.md","filePath":"explore-ic/research-directions/architecture.md","lastUpdated":1795531638000}'),p={name:"explore-ic/research-directions/architecture.md"};function A(g,e,f,_,C,b){const s=r("FacultyList"),h=r("CourseTable"),E=r("Mermaid");return n(),u("div",null,[e[1]||(e[1]=t('<h1 id="计算机体系结构与系统" tabindex="-1">计算机体系结构与系统 <a class="header-anchor" href="#计算机体系结构与系统" aria-label="Permalink to &quot;计算机体系结构与系统&quot;">​</a></h1><h2 id="这个方向在做什么" tabindex="-1">这个方向在做什么 <a class="header-anchor" href="#这个方向在做什么" aria-label="Permalink to &quot;这个方向在做什么&quot;">​</a></h2><p>计算机体系结构（Computer Architecture）研究计算系统向软件提供什么能力，以及如何组织执行、存储与通信来高效实现这些能力。指令集架构（ISA）是软硬件约定，微架构是具体实现；两者不是同义词。系统研究进一步把操作系统、编译器、运行时、存储与真实应用纳入分析，避免只优化一个脱离使用环境的硬件模块。</p><p>核心研究问题包括：</p><ul><li>流水线、乱序执行与分支预测如何隐藏延迟，又付出什么代价？</li><li>缓存、主存、互连和存储系统怎样支撑数据密集应用？</li><li>并行程序的同步、通信与负载不均衡如何限制扩展性？</li><li>CPU、GPU 和专用加速器应怎样分工，软件接口如何匹配？</li><li>性能、功耗、面积与安全机制之间如何取得可测量的权衡？</li></ul><h2 id="上科大谁在做" tabindex="-1">上科大谁在做 <a class="header-anchor" href="#上科大谁在做" aria-label="Permalink to &quot;上科大谁在做&quot;">​</a></h2><p>上科大相关研究跨越电路与系统两个层次。刘思廷的公开方向包含先进计算电路与系统，中心材料提及新型计算机系统架构、边缘 AI 与低比特计算。肖原关注系统安全、微架构、侧信道攻击、可信执行环境及 x86/RISC-V，体现了架构机制与安全问题的交叉。</p><p>王春东关注数据存储与管理、操作系统与体系结构、数据安全与隐私；殷树关注高性能计算和高性能文件系统。因此，“做体系结构”不只意味着从零写 CPU，也可能是围绕数据路径、软件栈或存储系统建立可复现的实验。下面的方向标签仅作导航，不表示这些团队都在研究 GPU。</p>',8)),i(s,{dir:"arch"}),e[2]||(e[2]=a("h2",{id:"相关上科大课程",tabindex:"-1"},[l("相关上科大课程 "),a("a",{class:"header-anchor",href:"#相关上科大课程","aria-label":'Permalink to "相关上科大课程"'},"​")],-1)),e[3]||(e[3]=a("p",null,[a("a",{href:"/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/cs110"},"CS110 计算机体系结构 I"),l(" 是整体入口，之后可按兴趣结合并行计算、操作系统、编译与智能计算课程。")],-1)),i(h,{codes:"CS100,CS110,CS110P,CS121,CS130,CS131,CS210,EE219,EE216"}),e[4]||(e[4]=t('<h3 id="用开源-gpgpu-建立研究对象" tabindex="-1">用开源 GPGPU 建立研究对象 <a class="header-anchor" href="#用开源-gpgpu-建立研究对象" aria-label="Permalink to &quot;用开源 GPGPU 建立研究对象&quot;">​</a></h3><p>通用 GPU 计算（GPGPU）是连接并行执行与完整软件栈的一条实践路线。<a href="https://github.com/vortexgpgpu/vortex" target="_blank" rel="noreferrer">Vortex</a> 基于 RISC-V 扩展提供开源 GPGPU 系统；<a href="https://github.com/THU-DSP-LAB/ventus-gpgpu" target="_blank" rel="noreferrer">乘影 Ventus</a> 则以 RISC-V 及向量扩展为基础探索 GPU 执行。可以围绕线程束调度、分支发散、访存合并与存储层级比较其设计，而不是只比较核心数量。</p><p>这些项目是公开学习与研究参照，不代表本校团队的项目归属，也不代表某门课程每年都会使用。入门建议先在原项目环境中跑通一个小程序，理解编译器、运行时、驱动与硬件的边界，再选一个局部机制做受控实验；具体接口和支持状态以项目当前文档为准。</p><h2 id="知识前置" tabindex="-1">知识前置 <a class="header-anchor" href="#知识前置" aria-label="Permalink to &quot;知识前置&quot;">​</a></h2><p>这是学习建议，不是正式先修表；架构研究也需要统计、实验设计与基本数字电路知识。</p>',5)),(n(),B(d,null,{default:o(()=>[i(E,{id:"mermaid-73",class:"mermaid",graph:"graph%20TD%0A%20%20A%5B%22CS100%20%E8%AE%A1%E7%AE%97%E6%9C%BA%E7%BC%96%E7%A8%8B%22%5D%20--%3E%20B%5B%22CS110%20%E8%AE%A1%E7%AE%97%E6%9C%BA%E4%BD%93%E7%B3%BB%E7%BB%93%E6%9E%84I%22%5D%0A%20%20C%5B%22EE115B%20%E6%95%B0%E5%AD%97%E7%94%B5%E8%B7%AF%22%5D%20--%3E%20B%0A%20%20B%20--%3E%20D%5B%22CS110P%20%E8%AE%A1%E7%AE%97%E6%9C%BA%E4%BD%93%E7%B3%BB%E7%BB%93%E6%9E%84I%E8%AF%BE%E7%A8%8B%E8%AE%BE%E8%AE%A1%22%5D%0A%20%20B%20--%3E%20E%5B%22CS130%20%E6%93%8D%E4%BD%9C%E7%B3%BB%E7%BB%9FI%22%5D%0A%20%20A%20--%3E%20F%5B%22CS131%20%E7%BC%96%E8%AF%91%E5%8E%9F%E7%90%86%22%5D%0A%20%20A%20--%3E%20G%5B%22CS121%20%E5%B9%B6%E8%A1%8C%E8%AE%A1%E7%AE%97%22%5D%0A%20%20B%20--%3E%20H%5B%22CS210%20%E8%AE%A1%E7%AE%97%E6%9C%BA%E4%BD%93%E7%B3%BB%E7%BB%93%E6%9E%84III%22%5D%0A%20%20E%20--%3E%20H%0A%20%20D%20--%3E%20I%5B%22RISC-V%20%E4%B8%8E%E5%A4%84%E7%90%86%E5%99%A8%E5%AE%9E%E8%B7%B5%22%5D%0A%20%20F%20--%3E%20J%5B%22GPGPU%20%E4%B8%8E%E5%BC%82%E6%9E%84%E7%B3%BB%E7%BB%9F%22%5D%0A%20%20G%20--%3E%20J%0A%20%20H%20--%3E%20J%0A%20%20I%20--%3E%20K%5B%22%E4%BD%93%E7%B3%BB%E7%BB%93%E6%9E%84%E4%B8%8E%E7%B3%BB%E7%BB%9F%E7%A0%94%E7%A9%B6%22%5D%0A%20%20J%20--%3E%20K%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=t('<h2 id="领域地图" tabindex="-1">领域地图 <a class="header-anchor" href="#领域地图" aria-label="Permalink to &quot;领域地图&quot;">​</a></h2><ul><li><strong>研究机构</strong>：Berkeley、MIT、Stanford、清华与中科院计算所是架构与系统研究的重要检索入口；Georgia Tech 的 Vortex 与清华 THU-DSP-LAB 的 Ventus 提供可阅读的开源 GPGPU 实例。</li><li><strong>产业参照</strong>：Intel、AMD、NVIDIA、Arm、华为海思的处理器与软件生态，适合对照指令集、微架构和系统接口的区别；不构成本校合作名单。</li><li><strong>会议与期刊</strong>：ISCA、MICRO、HPCA、ASPLOS，以及 ACM Transactions on Architecture and Code Optimization（TACO）、IEEE Transactions on Computers（TC）；操作系统与存储交叉问题还可关注 SOSP、OSDI、FAST。</li></ul><p>架构实验应固定程序版本、输入、编译参数和平台配置，分清模拟周期、硬件时钟与真实运行时间。模拟器中的提升、FPGA 结果和硅片实测各有证据边界，不能互相替代。</p><h2 id="入门资源" tabindex="-1">入门资源 <a class="header-anchor" href="#入门资源" aria-label="Permalink to &quot;入门资源&quot;">​</a></h2><ul><li><a href="/shanghaitech-ic-wiki-dev.github.io/learning/computer-architecture/general-purpose-systems">体系结构自学</a> 与 <a href="/shanghaitech-ic-wiki-dev.github.io/learning/digital-ic/resources">数字自学</a>：连接软件执行与硬件实现。</li><li><a href="https://riscv.org/" target="_blank" rel="noreferrer">RISC-V International</a>：标准与开放生态入口；使用规范时注意版本与扩展状态。</li><li><a href="https://github.com/vortexgpgpu/vortex" target="_blank" rel="noreferrer">Vortex 项目</a>、<a href="https://github.com/THU-DSP-LAB/ventus-gpgpu" target="_blank" rel="noreferrer">Ventus 项目</a>：以各自 README 和文档为准。</li><li><a href="https://ysyx.oscc.cc/" target="_blank" rel="noreferrer">一生一芯</a>：从处理器实现理解系统全栈。</li></ul><h2 id="社区经验征集" tabindex="-1">社区经验征集 <a class="header-anchor" href="#社区经验征集" aria-label="Permalink to &quot;社区经验征集&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">征集</p><p>欢迎相关课题组同学通过 <a href="/shanghaitech-ic-wiki-dev.github.io/community/contributing">参与共建</a> 补充“组里在做什么”、开源系统复现经验和进组准备建议；请给出版本与实验边界，不上传私有代码、账号或个人记录。</p></div><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://sist.shanghaitech.edu.cn/liust/main.htm" target="_blank" rel="noreferrer">刘思廷学院主页</a>、<a href="https://sist.shanghaitech.edu.cn/xy/main.htm" target="_blank" rel="noreferrer">肖原学院主页</a>、<a href="https://sist.shanghaitech.edu.cn/wangchd/main.htm" target="_blank" rel="noreferrer">王春东学院主页</a>、<a href="https://sist.shanghaitech.edu.cn/yinshu/main.htm" target="_blank" rel="noreferrer">殷树学院主页</a>。</li><li><a href="https://sist.shanghaitech.edu.cn/_upload/article/files/d0/82/218152ad4bd29c54d8a89d0e6be7/2cba84cd-d335-4a72-8f17-68175bed8e69.pdf" target="_blank" rel="noreferrer">后摩尔中心介绍材料</a>：约 2024 年计算系统方向介绍。</li><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">2026–2027 学年 SIST 开课计划</a>：实际开课与课程安排以教务系统为准。</li><li><a href="https://github.com/vortexgpgpu/vortex" target="_blank" rel="noreferrer">Vortex</a>、<a href="https://github.com/THU-DSP-LAB/ventus-gpgpu" target="_blank" rel="noreferrer">Ventus</a>：公开项目与技术文档，不引用个人课程笔记中的进度、评价或性能排名。</li></ul>',9))])}const P=c(p,[["render",A]]);export{S as __pageData,P as default};
